const { describe, it, beforeEach } = require('node:test');
const assert = require('node:assert/strict');
const ShoppingCart = require('../src/cart');

function assertCloseTo(actual, expected, epsilon = 1e-9) {
  assert.ok(
    Math.abs(actual - expected) < epsilon,
    `expected ${actual} to be close to ${expected}`
  );
}

describe('ShoppingCart', () => {
  let cart;

  beforeEach(() => {
    cart = new ShoppingCart();
  });

  describe('constructor', () => {
    it('starts empty with no discount', () => {
      assert.deepEqual(cart.items, []);
      assert.equal(cart.discount, 0);
      assert.equal(cart.getItemCount(), 0);
    });
  });

  describe('addItem', () => {
    it('adds a new item', () => {
      cart.addItem('apple', 1.5, 2);
      assert.deepEqual(cart.items, [{ name: 'apple', price: 1.5, quantity: 2 }]);
      assert.equal(cart.getItemCount(), 1);
    });

    it('adds multiple distinct items', () => {
      cart.addItem('apple', 1, 1);
      cart.addItem('banana', 2, 3);
      assert.equal(cart.getItemCount(), 2);
    });

    it('merges quantities when the same item is added again', () => {
      cart.addItem('apple', 1, 2);
      cart.addItem('apple', 1, 3);
      assert.equal(cart.getItemCount(), 1);
      assert.equal(cart.items[0].quantity, 5);
    });

    it('allows a price of 0 (free item)', () => {
      cart.addItem('sticker', 0, 1);
      assert.equal(cart.getItemCount(), 1);
      assert.equal(cart.getTotal(), 0);
    });

    // Regression tests for Bug 1: negative price/quantity were accepted.
    describe('Bug 1: rejects invalid price and quantity', () => {
      it('throws on a negative price', () => {
        assert.throws(() => cart.addItem('apple', -1, 1), RangeError);
        assert.equal(cart.getItemCount(), 0);
      });

      it('throws on a negative quantity', () => {
        assert.throws(() => cart.addItem('apple', 1, -1), RangeError);
        assert.equal(cart.getItemCount(), 0);
      });

      it('does not let a negative quantity reduce an existing item', () => {
        cart.addItem('apple', 1, 5);
        assert.throws(() => cart.addItem('apple', 1, -3), RangeError);
        assert.equal(cart.items[0].quantity, 5);
      });

      it('does not let a negative price produce a negative total', () => {
        assert.throws(() => cart.addItem('refund', -50, 1), RangeError);
        assert.equal(cart.getTotal(), 0);
      });

      it('throws on a zero quantity', () => {
        assert.throws(() => cart.addItem('apple', 1, 0), RangeError);
        assert.equal(cart.getItemCount(), 0);
      });

      it('throws on a fractional quantity', () => {
        assert.throws(() => cart.addItem('apple', 1, 1.5), RangeError);
      });

      for (const bad of [NaN, Infinity, '10', null, undefined]) {
        it(`throws on non-numeric or non-finite price: ${String(bad)}`, () => {
          assert.throws(() => cart.addItem('apple', bad, 1), RangeError);
          assert.equal(cart.getItemCount(), 0);
        });

        it(`throws on non-numeric or non-finite quantity: ${String(bad)}`, () => {
          assert.throws(() => cart.addItem('apple', 1, bad), RangeError);
          assert.equal(cart.getItemCount(), 0);
        });
      }
    });
  });

  describe('removeItem', () => {
    beforeEach(() => {
      cart.addItem('apple', 1, 1);
      cart.addItem('banana', 2, 1);
      cart.addItem('cherry', 3, 1);
    });

    // Regression tests for Bug 2: `i.name = name` assigned instead of compared,
    // so nothing was removed and every item was renamed.
    describe('Bug 2: filters by comparison, not assignment', () => {
      it('removes only the named item', () => {
        cart.removeItem('banana');
        assert.deepEqual(
          cart.items.map(i => i.name),
          ['apple', 'cherry']
        );
      });

      it('does not rename the remaining items', () => {
        cart.removeItem('apple');
        assert.ok(cart.items.every(i => i.name !== 'apple'));
        assert.deepEqual(
          cart.items.map(i => i.name),
          ['banana', 'cherry']
        );
      });

      it('updates the item count and total after removal', () => {
        cart.removeItem('cherry');
        assert.equal(cart.getItemCount(), 2);
        assert.equal(cart.getTotal(), 3);
      });

      it('returns true when an item is removed', () => {
        assert.equal(cart.removeItem('apple'), true);
      });

      it('returns false and leaves the cart unchanged for a missing item', () => {
        const before = structuredClone(cart.items);
        assert.equal(cart.removeItem('durian'), false);
        assert.deepEqual(cart.items, before);
      });

      it('returns false when removing from an empty cart', () => {
        const empty = new ShoppingCart();
        assert.equal(empty.removeItem('apple'), false);
        assert.equal(empty.getItemCount(), 0);
      });

      it('returns false when removing the same item twice', () => {
        assert.equal(cart.removeItem('apple'), true);
        assert.equal(cart.removeItem('apple'), false);
        assert.equal(cart.getItemCount(), 2);
      });
    });
  });

  describe('getTotal', () => {
    // Regression tests for Bug 3: `i <= length` read past the end of the array
    // and threw a TypeError on every call.
    describe('Bug 3: iterates items without going out of bounds', () => {
      it('returns 0 for an empty cart', () => {
        assert.equal(cart.getTotal(), 0);
      });

      it('returns the price times quantity for a single item', () => {
        cart.addItem('apple', 2, 3);
        assert.equal(cart.getTotal(), 6);
      });

      it('sums every item across the cart', () => {
        cart.addItem('apple', 1, 2);
        cart.addItem('banana', 2, 3);
        cart.addItem('cherry', 5, 1);
        assert.equal(cart.getTotal(), 13);
      });
    });

    it('handles decimal prices', () => {
      cart.addItem('book', 19.99, 3);
      assertCloseTo(cart.getTotal(), 59.97);
    });

    it('reflects merged quantities', () => {
      cart.addItem('apple', 2, 1);
      cart.addItem('apple', 2, 4);
      assert.equal(cart.getTotal(), 10);
    });

    // Regression tests for Bug 4: discount was added to the total.
    describe('Bug 4: subtracts the discount', () => {
      it('reduces the total by the discount percentage', () => {
        cart.addItem('tv', 100, 1);
        cart.applyDiscount(10);
        assert.equal(cart.getTotal(), 90);
      });

      it('never makes the discounted total greater than the undiscounted total', () => {
        cart.addItem('tv', 250, 2);
        const full = cart.getTotal();
        cart.applyDiscount(25);
        assert.ok(cart.getTotal() < full);
        assert.equal(cart.getTotal(), 375);
      });

      it('returns 0 with a 100% discount', () => {
        cart.addItem('tv', 100, 1);
        cart.applyDiscount(100);
        assert.equal(cart.getTotal(), 0);
      });

      it('returns the full total with a 0% discount', () => {
        cart.addItem('tv', 100, 1);
        cart.applyDiscount(0);
        assert.equal(cart.getTotal(), 100);
      });

      it('applies the discount to items added after it was set', () => {
        cart.applyDiscount(50);
        cart.addItem('tv', 100, 1);
        cart.addItem('remote', 20, 1);
        assert.equal(cart.getTotal(), 60);
      });

      it('handles fractional discount percentages', () => {
        cart.addItem('tv', 200, 1);
        cart.applyDiscount(12.5);
        assertCloseTo(cart.getTotal(), 175);
      });
    });
  });

  describe('applyDiscount', () => {
    it('stores a valid discount', () => {
      cart.applyDiscount(20);
      assert.equal(cart.discount, 20);
    });

    it('replaces a previous discount rather than stacking', () => {
      cart.addItem('tv', 100, 1);
      cart.applyDiscount(10);
      cart.applyDiscount(30);
      assert.equal(cart.getTotal(), 70);
    });

    it('accepts the boundary values 0 and 100', () => {
      assert.doesNotThrow(() => cart.applyDiscount(0));
      assert.doesNotThrow(() => cart.applyDiscount(100));
    });

    // Regression tests for Bug 5: any discount value was accepted.
    describe('Bug 5: validates the discount range', () => {
      it('throws on a discount above 100', () => {
        assert.throws(() => cart.applyDiscount(101), RangeError);
      });

      it('throws on a negative discount', () => {
        assert.throws(() => cart.applyDiscount(-10), RangeError);
      });

      it('keeps the previous discount when an invalid one is rejected', () => {
        cart.addItem('tv', 100, 1);
        cart.applyDiscount(10);
        assert.throws(() => cart.applyDiscount(150), RangeError);
        assert.equal(cart.discount, 10);
        assert.equal(cart.getTotal(), 90);
      });

      it('never allows the total to go negative', () => {
        cart.addItem('tv', 100, 1);
        assert.throws(() => cart.applyDiscount(150), RangeError);
        assert.ok(cart.getTotal() >= 0);
      });

      it('never allows a negative discount to inflate the total', () => {
        cart.addItem('tv', 100, 1);
        assert.throws(() => cart.applyDiscount(-50), RangeError);
        assert.equal(cart.getTotal(), 100);
      });

      for (const bad of [NaN, Infinity, '10', null, undefined]) {
        it(`throws on non-numeric or non-finite discount: ${String(bad)}`, () => {
          assert.throws(() => cart.applyDiscount(bad), RangeError);
          assert.equal(cart.discount, 0);
        });
      }
    });
  });
});

